#!/usr/bin/env bash
# GSZ step126 — warranty per product (+ per-plan override), shown on the product
# page, auto-omitted for player-activation (MAC) types. Files: adminCatalog.js,
# product_edit.ejs, products.js, product.ejs + migration. Safe + idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step126-$TS"; TMP=$(mktemp -d)
FILES=(routes/adminCatalog.js views/admin/product_edit.ejs routes/products.js views/product.ejs)
echo "==> step126: warranty per product/plan"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/adminCatalog.js"; node --check "$GSZ/routes/products.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/product_edit.ejs','views/product.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then PC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/product/$SLUG" || true); [ "$PC" = "200" ] && echo "    product page renders ($SLUG): OK" || { echo "    product $PC"; false; }; fi
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step126 OK ✅"
echo "    • Product editor: a product-level Warranty field + an optional per-plan override."
echo "    • Product page shows the selected plan's warranty (plan override, else product default)."
echo "    • Auto-omitted for player-activation (MAC) plans."
